import React from "react";
import "./Layout.css";

const Layout = ({ header, asideIzq, main, asideDer }) => {
  return (
    <div className="layout-grid">
      <header className="layout-header">{header}</header>
      <aside className="layout-aside-izq">{asideIzq}</aside>
      <main className="layout-main">{main}</main>
      <aside className="layout-aside-der">{asideDer}</aside>
      <footer className="layout-footer">
        <p>© 2025 MySpace - Todos los derechos reservados</p>
      </footer>
    </div>
  );
};

export default Layout;
